import React, { useState, useEffect, useRef } from "react";

export default function StorageTransfer({
  categories,
  storages,
  onAddTransfer,
  onRemoveTransfer,
  onUpdateTransfer,
  transfers = []
}) {
  const [showFromStorageDropdown, setShowFromStorageDropdown] = useState(false);
  const [showToStorageDropdown, setShowToStorageDropdown] = useState(false);
  const [activeDropdown, setActiveDropdown] = useState(null);
  const dropdownRef = useRef(null);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setShowFromStorageDropdown(false);
        setShowToStorageDropdown(false);
        setActiveDropdown(null);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const handleStorageToggle = (storageId, isFromStorage = true) => {
    const currentTransfers = [...transfers];
    const lastTransfer = currentTransfers[currentTransfers.length - 1];

    if (!lastTransfer) {
      // Create new transfer if none exists
      const newTransfer = {
        id: Date.now() + Math.random(),
        category: "",
        quantity: "",
        weight: "",
        fromStorage: isFromStorage ? storageId : "",
        toStorage: isFromStorage ? "" : storageId
      };
      onAddTransfer(newTransfer);
    } else {
      // Update existing transfer
      const updatedTransfer = {
        ...lastTransfer,
        fromStorage: isFromStorage ? storageId : lastTransfer.fromStorage,
        toStorage: isFromStorage ? lastTransfer.toStorage : storageId
      };
      onUpdateTransfer(updatedTransfer);
    }
  };

  const getDisplayText = (storageIds, isFromStorage) => {
    if (!storageIds || storageIds.length === 0) {
      return isFromStorage ? "From Storage" : "To Storage";
    }

    const storageNames = storageIds.split('/').map(storageId => {
      const storage = storages.find(s => s.id === storageId);
      return storage ? storage.name : storageId;
    });
    return storageNames.join(' / ');
  };

  const addNewTransfer = () => {
    const newTransfer = {
      id: Date.now() + Math.random(),
      category: "",
      quantity: "",
      weight: "",
      fromStorage: "",
      toStorage: ""
    };
    onAddTransfer(newTransfer);
  };

  return (
    <div className="storage-transfer-section">
      <div className="section-header">
        <h3>Storage Transfers (Relocate Products)</h3>
        <p className="section-description">
          Use leftover truck capacity to relocate products between storages
        </p>
      </div>

      {transfers.map((transfer, index) => (
        <div key={transfer.id} className="transfer-row">
          {/* Category dropdown */}
          <div className="cell">
            <select
              className="input category-input"
              value={transfer.category}
              onChange={(e) => onUpdateTransfer({...transfer, category: e.target.value})}
            >
              <option value="">Select Category</option>
              {categories.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.name}
                </option>
              ))}
            </select>
          </div>

          {/* Quantity input */}
          <div className="cell">
            <input
              className="input quantity-input"
              type="text"
              placeholder="Quantity"
              value={transfer.quantity}
              onChange={(e) => onUpdateTransfer({...transfer, quantity: e.target.value})}
            />
          </div>

          {/* Weight input */}
          <div className="cell">
            <input
              className="input weight-input"
              type="text"
              placeholder="Weight"
              value={transfer.weight}
              onChange={(e) => onUpdateTransfer({...transfer, weight: e.target.value})}
            />
          </div>

          {/* From Storage dropdown */}
          <div className="cell">
            <div className="multi-select-container" ref={dropdownRef}>
              <div 
                className="input storage-input multi-select-trigger"
                onClick={() => {
                  setShowFromStorageDropdown(!showFromStorageDropdown);
                  setShowToStorageDropdown(false);
                  setActiveDropdown('from');
                }}
              >
                <span>{getDisplayText(transfer.fromStorage, true)}</span>
                <span className="dropdown-arrow">▼</span>
              </div>

              {showFromStorageDropdown && activeDropdown === 'from' && (
                <div className="multi-select-dropdown">
                  {storages.map((storage) => (
                    <div 
                      key={storage.id} 
                      className="storage-option"
                      onClick={() => handleStorageToggle(storage.id, true)}
                    >
                      <input
                        type="checkbox"
                        checked={transfer.fromStorage && transfer.fromStorage.includes(storage.id)}
                        onChange={() => {}} // Controlled by onClick
                        className="storage-checkbox"
                      />
                      <span className="storage-name">{storage.name}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Transfer arrow */}
          <div className="cell transfer-arrow">
            <span>→</span>
          </div>

          {/* To Storage dropdown */}
          <div className="cell">
            <div className="multi-select-container">
              <div 
                className="input storage-input multi-select-trigger"
                onClick={() => {
                  setShowToStorageDropdown(!showToStorageDropdown);
                  setShowFromStorageDropdown(false);
                  setActiveDropdown('to');
                }}
              >
                <span>{getDisplayText(transfer.toStorage, false)}</span>
                <span className="dropdown-arrow">▼</span>
              </div>

              {showToStorageDropdown && activeDropdown === 'to' && (
                <div className="multi-select-dropdown">
                  {storages.map((storage) => (
                    <div 
                      key={storage.id} 
                      className="storage-option"
                      onClick={() => handleStorageToggle(storage.id, false)}
                    >
                      <input
                        type="checkbox"
                        checked={transfer.toStorage && transfer.toStorage.includes(storage.id)}
                        onChange={() => {}} // Controlled by onClick
                        className="storage-checkbox"
                      />
                      <span className="storage-name">{storage.name}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Remove transfer row */}
          <div className="remove-transfer-cell">
            <button 
              className="btn remove-transfer-btn" 
              onClick={() => onRemoveTransfer(transfer.id)}
            >
              ×
            </button>
          </div>
        </div>
      ))}

      <div className="add-transfer-row">
        <button className="btn add-transfer-btn" onClick={addNewTransfer}>
          + Add Transfer
        </button>
      </div>
    </div>
  );
}
